function runtimeLabel(id,engine){return id==="docker"&&engine==="podman"?"Podman (Docker CLI)":id==="podman"?"Podman":id==="docker"?"Docker":String(id??"Runtime")}function canonicalRuntimeId(runtimes,id){return runtimes?.find(runtime=>runtime.id===id||runtime.aliases?.includes(id??""))?.id??id}function resourceKey(item){return JSON.stringify([item.runtime,item.kind,item.id,item.kind==="image"?item.ref:null])}function resourceRequest(item){return{id:item.id,runtime:item.runtime}}export{runtimeLabel,canonicalRuntimeId,resourceKey,resourceRequest};
